DELETE FROM idempotency_records
WHERE user_id = #{userId}
  AND operation = #{operation}
  AND idempotency_key = #{idempotencyKey}
  AND expires_at <= #{now}

DELETE FROM idempotency_records
WHERE id IN (
    SELECT id
    FROM idempotency_records
    WHERE expires_at <= #{now}
    ORDER BY expires_at
    LIMIT #{limit}
)
